class Solution:
    def waysToMakeFair(self, nums: List[int]) -> int:
        n = len(nums)
        ans = 0
        for i in range(n):
            even = odd = 0
            for j in range(n):
                if j == i:
                    continue
                jj = j if j < i else j - 1
                if jj % 2 == 0:
                    even += nums[j]
                else:
                    odd += nums[j]
            if even == odd:
                ans += 1
        return ans

