class Solution:
    def waysToMakeFair(self, nums: List[int]) -> int:
        total_e = sum(nums[::2])
        total_o = sum(nums[1::2])
        pre_e = pre_o = 0
        ans = 0
        for i, v in enumerate(nums):
            suf_e = total_e - pre_e - (v if i % 2 == 0 else 0)
            suf_o = total_o - pre_o - (v if i % 2 == 1 else 0)
            if pre_e + suf_o == pre_o + suf_e:
                ans += 1
            if i % 2 == 0:
                pre_e += v
            else:
                pre_o += v
        return ans

