        for (int i = 0; i < (int)nums.size(); i++)
            (i % 2 == 0 ? totE : totO) += nums[i];
        long long preE = 0, preO = 0;
        int ans = 0;
        for (int i = 0; i < (int)nums.size(); i++) {
            long long sufE = totE - preE - (i % 2 == 0 ? nums[i] : 0);
            long long sufO = totO - preO - (i % 2 == 1 ? nums[i] : 0);
            if (preE + sufO == preO + sufE) ans++;
            if (i % 2 == 0) preE += nums[i];
            else preO += nums[i];
        }
        return ans;
    }
};

